pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool success,) = address(c).call{value: amount}("");
        require(success, "deposit failed");

        uint256 balBefore = address(c).balance;
        uint256 userBal = c.balances(actor);
        vm.prank(actor);
        try c.withdraw() { } catch { }
        uint256 balAfter = address(c).balance;

        assertTrue(balAfter == balBefore - userBal);
    }
}
